// Invoice Processing Automation: core logic (ported from main.py)
const KNOWN_SUPPLIERS = [
 "Lagos Office Supplies Ltd",
 "Eko Power Solutions",
 "Ikeja Print House",
 "Apapa Logistics Co"
];
// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const MONEY = '([0-9][0-9,]*\\.?[0-9]*)';
const num = s => Number(String(s).replace(/,/g, ''));
function extract(text) {
  const find = re => { const m = text.match(re); return m ? m[1].trim() : null; };
  const items = []; let m;
  const re = new RegExp('^\\s*-\\s*(.+?)\\s+(\\d+)\\s*x\\s*' + MONEY + '\\s*=\\s*' + MONEY, 'gm');
  while ((m = re.exec(text))) items.push({ description: m[1].trim(), qty: +m[2], unit_price: num(m[3]), amount: num(m[4]) });
  const sub = find(new RegExp('^Subtotal:?\\s*' + MONEY, 'mi')), vat = find(new RegExp('^VAT.*?:\\s*' + MONEY, 'mi')),
        tot = find(new RegExp('^Total:?\\s*' + MONEY, 'mi'));
  return { supplier: find(/^Supplier:?\s*(.+)$/mi), invoice_number: find(/^Invoice\s*(?:No|Number|#)\.?:?\s*(\S+)/mi),
           invoice_date: find(/^Date:?\s*(.+)$/mi), due_date: find(/^Due:?\s*(.+)$/mi), line_items: items,
           subtotal: sub ? num(sub) : null, vat: vat ? num(vat) : 0, total: tot ? num(tot) : null };
}
const r2 = x => Math.round(x * 100) / 100;
const seen = new Set(), out = [];
for (const doc of input) {
  const inv = extract(doc.text || ''), reasons = [];
  for (const f of ['supplier', 'invoice_number', 'total']) if (!inv[f]) reasons.push('missing ' + f);
  for (const i of inv.line_items) if (r2(i.qty * i.unit_price) !== r2(i.amount)) reasons.push(`line '${i.description}' does not add up`);
  const itemsSum = r2(inv.line_items.reduce((s, i) => s + i.amount, 0));
  if (inv.subtotal !== null && itemsSum !== r2(inv.subtotal)) reasons.push(`line items add to ${itemsSum} but subtotal says ${inv.subtotal}`);
  if (inv.subtotal !== null && inv.total !== null && r2(inv.subtotal + inv.vat) !== r2(inv.total))
    reasons.push(`subtotal + VAT = ${r2(inv.subtotal + inv.vat)} but total says ${inv.total}`);
  if (inv.supplier && !KNOWN_SUPPLIERS.includes(inv.supplier)) reasons.push(`unknown supplier '${inv.supplier}'`);
  const key = inv.supplier + '|' + inv.invoice_number;
  if (seen.has(key)) reasons.push('duplicate of invoice ' + inv.invoice_number);
  seen.add(key);
  out.push({ route: reasons.length ? 'review' : 'post', source: doc.source, supplier: inv.supplier,
             invoice_number: inv.invoice_number, invoice_date: inv.invoice_date, due_date: inv.due_date,
             subtotal: inv.subtotal, vat: inv.vat, total: inv.total, reasons: reasons.join('; ') });
}
return out.map(json => ({ json }));
